for (auto face_it = triangulation.finite_faces_begin(); face_it != triangulation.finite_faces_end(); ++face_it) {
    face_it->info().interior = false;
    face_it->info().processed = false;
}

std::queue<typename Triangulation::Face_handle> queue;
typename Triangulation::Face_handle seed_face = nullptr;

for (auto face_it = triangulation.finite_faces_begin(); face_it != triangulation.finite_faces_end(); ++face_it) {
    if (!seed_face && !triangulation.is_constrained(face_it->edge(0)) && !triangulation.is_constrained(face_it->edge(1)) && !triangulation.is_constrained(face_it->edge(2))) {
        seed_face = face_it;
        break;
    }
}

if (!seed_face) {
    for (auto face_it = triangulation.finite_faces_begin(); face_it != triangulation.finite_faces_end(); ++face_it) {
        if (!triangulation.is_constrained(face_it->edge(0)) || !triangulation.is_constrained(face_it->edge(1)) || !triangulation.is_constrained(face_it->edge(2))) {
            seed_face = face_it;
            break;
        }
    }
}

if (seed_face) {
    seed_face->info().interior = true;
    seed_face->info().processed = true;
    queue.push(seed_face);
}

while (!queue.empty()) {
    auto current_face = queue.front();
    queue.pop();

    for (int i = 0; i < 3; ++i) {
        auto neighbor = current_face->neighbor(i);
        if (triangulation.is_constrained(current_face->edge(i))) continue;
        if (neighbor->info().processed) continue;

        neighbor->info().interior = !current_face->info().interior;
        neighbor->info().processed = true;
        queue.push(neighbor);
    }
}

